  contactId: ctx.contactId,
  dealer: ctx.dealer,
  nombre: ctx.nombre,
  vehiculo_interes: ctx.vehiculo_interes,
  created_at: $now.toISO(),
  updated_at: $now.toISO()
};

if (params.tipo_agendamiento && params.tipo_agendamiento !== 'null') data.tipo = params.tipo_agendamiento;
if (params.fecha_hora && params.fecha_hora !== 'null') data.fecha_hora = params.fecha_hora;
if (params.horario_preferido && params.horario_preferido !== 'null') data.horario_preferido = params.horario_preferido;
if (params.medio_llamada && params.medio_llamada !== 'null') data.medio_llamada = params.medio_llamada;
if (params.cita_confirmada) data.confirmada = params.cita_confirmada;

