const ctx = $('CONTEXT').item.json;
const params = $('Parse RSVP Output').item.json.output.parameters;

const tipoLabel = {
  'cita_presencial': 'Visita presencial al concesionario',
  'cita_virtual': 'Videollamada con un asesor',
  'llamada': 'Llamada telefónica'
}[params.tipo_agendamiento] || '-';

const fechaIso = params.fecha_hora || $('Find Appointment').first().json.fecha_hora;
let fecha = '-';
if (fechaIso) {
  const dt = DateTime.fromISO(fechaIso, { zone: 'America/New_York' });
  if (dt.isValid) {
    const txt = dt.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' h:mm a");
    fecha = (txt.charAt(0).toUpperCase() + txt.slice(1)) + ' (hora Miami)';
  }
}
const medioLlamadaLabel = params.medio_llamada === 'whatsapp' ? 'WhatsApp' : params.medio_llamada === 'telefono' ? 'Teléfono' : '-';

return [{ json: {
  fecha,
  modalidad: tipoLabel,
  tipo_agendamiento: params.tipo_agendamiento || null,
  horario_preferido: params.horario_preferido || null,
  medio_llamada: params.medio_llamada || null,
  medio_llamada_label: medioLlamadaLabel
} }];

const raw = $input.first().json.output || '';

// deepseek-v4-flash a veces genera un rambling de razonamiento antes de la respuesta final,
// repitiendo el JSON de salida varias veces (mismo patron visto en KB-SEARCH 08-31,
// LEAD-COLLECTOR y PRINCIPAL 09-01). Un regex greedy 'primer { a ultimo }' mezcla varios
// bloques y JSON.parse falla. En vez de eso: extraer TODOS los objetos JSON balanceados
// (respetando strings y llaves anidadas) y quedarnos con el ULTIMO que parsea y tiene
// la clave 'parameters' -- es la version final y mas confiable del modelo.
function extraerObjetosJson(texto) {
  const resultados = [];
  for (let i = 0; i < texto.length; i++) {
    if (texto[i] !== '{') continue;
    let profundidad = 0;
    let enString = false;
    let escape = false;
    for (let j = i; j < texto.length; j++) {
      const c = texto[j];
      if (escape) { escape = false; continue; }
      if (c === '\\') { escape = true; continue; }
      if (c === '"') { enString = !enString; continue; }
      if (enString) continue;
      if (c === '{') profundidad++;
      else if (c === '}') {
        profundidad--;
        if (profundidad === 0) {
          resultados.push(texto.slice(i, j + 1));
          break;
        }
      }
    }
  }
  return resultados;
}

function extractJSON(text) {
  const candidatos = extraerObjetosJson(text);
  for (let i = candidatos.length - 1; i >= 0; i--) {
    try {
      const obj = JSON.parse(candidatos[i]);
      if (obj && typeof obj === 'object' && Object.prototype.hasOwnProperty.call(obj, 'parameters')) {
        return obj;
      }
    } catch (e) { /* seguir probando candidatos anteriores */ }
  }
  return null;
}

const parsed = extractJSON(raw);

if (!parsed) {
  return [{
    json: {
      output: {
        response: raw,
        parameters: {
          tipo_agendamiento: null,
          horario_preferido: null,
          medio_llamada: null,
          fecha_hora: null,
          cita_confirmada: false,
          cancelar_cita: false
        }
      }
    }
  }];
}

const p = parsed.parameters || {};
const norm = (v) => (v === 'null' || v === '' || v === undefined) ? null : v;

return [{
  json: {
    output: {
      response: parsed.response || raw,
      parameters: {
        tipo_agendamiento: norm(p.tipo_agendamiento),
        horario_preferido: norm(p.horario_preferido),
        medio_llamada: (() => { const v = norm(p.medio_llamada); if (!v) return null; const s = String(v).toLowerCase().replace(/[^a-z]/g, ''); if (s.includes('whats')) return 'whatsapp'; if (s.includes('telef') || s.includes('phone') || s === 'tel') return 'telefono'; return s === 'telefono' || s === 'whatsapp' ? s : null; })(),
        fecha_hora: (() => {
          const rawFecha = norm(p.fecha_hora);
          if (rawFecha) {
            const local = rawFecha.replace(/(\.[0-9]+)?(Z|[+-]\d{2}:?\d{2})$/, '');
            const dt = DateTime.fromISO(local, { zone: 'America/New_York' });
            return dt.isValid ? dt.toISO({ suppressMilliseconds: true }) : null;
          }
          if (norm(p.tipo_agendamiento) === 'llamada' && norm(p.horario_preferido)) {
            const horario = p.horario_preferido.toLowerCase().trim();
            let hour = null, minute = 0;

            const despuesM = horario.match(/(?:despu[ee]s\s+de\s+las?|a\s+partir\s+de\s+las?)\s+(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?/);
            const rangoM = !despuesM && horario.match(/de\s+las?\s+(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?/);
            const horaM = !despuesM && !rangoM && horario.match(/\b(\d{1,2})(?::(\d{2}))?\s*(a\.?m\.?|p\.?m\.)\b/);
            const hora24M = !despuesM && !rangoM && !horaM && horario.match(/\b(\d{1,2}):(\d{2})\b/);

            const matchUsado = despuesM || rangoM || horaM || hora24M;

            if (matchUsado) {
              hour = parseInt(matchUsado[1]);
              minute = matchUsado[2] ? parseInt(matchUsado[2]) : 0;
              const ampm = ((matchUsado[3] || '').replace(/[.\s]/g, '')).toLowerCase();
              if (ampm === 'pm' && hour < 12) hour += 12;
              else if (ampm === 'am' && hour === 12) hour = 0;
            } else if (/mediod[ii]a|medio\s+d[ii]a/.test(horario)) {
              hour = 12; minute = 0;
            } else if (/\btarde\b/.test(horario)) {
              hour = 14; minute = 0;
            } else if (/\bnoche\b/.test(horario)) {
              hour = 19; minute = 0;
            } else if (/\bma[nn]ana\b/.test(horario)) {
              hour = 9; minute = 0;
            } else if (/ahorita|ahora|\bya\b/.test(horario)) {
              const et = $now.setZone('America/New_York');
              const dt = et.plus({ hours: 1 }).set({ minute: 0, second: 0, millisecond: 0 });
              return dt.toISO({ suppressMilliseconds: true });
            }

            if (hour !== null) {
              const et = $now.setZone('America/New_York');
              let dt = et.set({ hour, minute, second: 0, millisecond: 0 });
              if (dt <= et) dt = dt.plus({ days: 1 });
              return dt.toISO({ suppressMilliseconds: true });
            }
          }
          return null;
        })(),
        cita_confirmada: p.cita_confirmada === true,
        cancelar_cita: p.cancelar_cita === true
      }
    }
  }
}];

function extractHex(val) {
  if (!val) return null;
  if (typeof val === 'string') return val.replace(/^"(.*)"$/, '$1');
  if (val.buffer) return Object.values(val.buffer).map(b => b.toString(16).padStart(2, '0')).join('');
  if (typeof val.toHexString === 'function') return val.toHexString();
  const s = (val.toString && typeof val.toString === 'function') ? val.toString().replace(/^"(.*)"$/, '$1') : '';
  return s && s !== '[object Object]' ? s : null;
}

const ap = $('Find Appointment').first().json;
const tipoLabel = {
  cita_presencial: 'visita presencial',
  cita_virtual: 'videollamada',
  llamada: 'llamada'
}[ap.tipo] || 'cita';

let fechaTxt = '';
let fechaFmt = '—';
if (ap.fecha_hora) {
  const dt = DateTime.fromISO(ap.fecha_hora, { zone: 'America/New_York' }).setLocale('es');
  if (dt.isValid) {
    fechaTxt = ` del ${dt.toFormat("cccc d 'de' LLLL")}`;
    fechaFmt = dt.toFormat("cccc d 'de' LLLL 'a las' h:mm a") + ' (hora Miami)';
  }
}

return [{ json: {
  _id: extractHex(ap._id || ap.id),
  confirmada: false,
  cancelada: true,
  updated_at: $now.toISO(),
  response_override: `Listo, tu ${tipoLabel}${fechaTxt} fue cancelada. ¿Quieres agendar otra?`,
  fecha_fmt: fechaFmt,
  modalidad_fmt: tipoLabel
} }];

function extractHex(val) {
  if (!val) return null;
  if (typeof val === 'string') return val.replace(/^"(.*)"$/, '$1');
  if (val.buffer) return Object.values(val.buffer).map(b => b.toString(16).padStart(2, '0')).join('');
  if (typeof val.toHexString === 'function') return val.toHexString();
  const s = (val.toString && typeof val.toString === 'function') ? val.toString().replace(/^"(.*)"$/, '$1') : '';
  return s && s !== '[object Object]' ? s : null;
}

const params = $('Parse RSVP Output').first().json.output.parameters;
const existing = $('Find Appointment').first().json;
const ghlEventId = existing && existing.ghl_event_id ? existing.ghl_event_id : null;

let _id;
try { _id = $('Insert Appointment').first().json._id; } catch(e) {}
if (!_id) { try { _id = $('Update Appointment').first().json._id; } catch(e) {} }
if (!_id) { try { _id = existing && existing._id; } catch(e) {} }
_id = extractHex(_id);

const fechaHora = params.fecha_hora;

if (!fechaHora) {
  return [{ json: {
    accion: 'no_disponible', _id, ghl_event_id: ghlEventId,
    confirmada: false, updated_at: $now.toISO(),
    response_override: 'No pude registrar el horario exacto. ¿Puedes confirmarme el día y la hora de nuevo?'
  } }];
}

const requested = DateTime.fromISO(fechaHora, { zone: 'America/New_York' });
const dayKey = requested.toFormat('yyyy-MM-dd');
const slotsResp = $('GHL Consultar Disponibilidad').first().json;
const daySlots = (slotsResp[dayKey] && slotsResp[dayKey].slots) || [];

const match = daySlots.find(s => Math.abs(DateTime.fromISO(s).toMillis() - requested.toMillis()) < 60 * 1000);

if (!match) {
  const future = daySlots.filter(s => DateTime.fromISO(s).toMillis() >= requested.toMillis());
  const suggestion = future[0] || daySlots[0] || null;
  let suggestionText = 'no tenemos horarios disponibles ese día, ¿prefieres otro día?';
  if (suggestion) {
    const dt = DateTime.fromISO(suggestion).setLocale('es');
    suggestionText = `el horario más cercano disponible es ${dt.toFormat("cccc d 'de' LLLL 'a las' h:mm a")} (hora Miami). ¿Te sirve o prefieres otro?`;
  }
  return [{ json: {
    accion: 'no_disponible', _id, ghl_event_id: ghlEventId,
    confirmada: false, updated_at: $now.toISO(),
    response_override: `Ese horario ya no está disponible — ${suggestionText}`
  } }];
}

const startIso = match;
const endIso = DateTime.fromISO(match).plus({ minutes: 35 }).toISO({ suppressMilliseconds: true });

const tipoPrefix = {
  cita_presencial: 'Visita presencial (incluye test drive) — ',
  cita_virtual: 'Videollamada con asesor — '
}[params.tipo_agendamiento] || '';

return [{ json: {
  accion: ghlEventId ? 'reagendar' : 'crear',
  _id, ghl_event_id: ghlEventId,
  slot_iso: startIso, end_iso: endIso,
  titulo: `${tipoPrefix}CarWarriors`
} }];
